
-- Delete old templates and re-insert with beautiful HTML
DELETE FROM public.email_templates WHERE workspace_id IS NULL;

INSERT INTO public.email_templates (workspace_id, slug, locale, subject, html_body, text_body, is_active) VALUES

-- ═══════════════════════════════════════════
-- EMAIL VERIFY
-- ═══════════════════════════════════════════
(NULL, 'email_verify', 'en', 'Verify your email', '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f5;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,''Helvetica Neue'',Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f5;padding:40px 20px;"><tr><td align="center"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 6px rgba(0,0,0,0.07);"><tr><td style="background:linear-gradient(135deg,#3B82F6,#2563EB);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:24px;font-weight:700;">✉️ Email Verification</h1></td></tr><tr><td style="padding:40px;"><p style="margin:0 0 16px;font-size:16px;color:#374151;">Hi <strong>{name}</strong>,</p><p style="margin:0 0 24px;font-size:16px;color:#374151;line-height:1.6;">Thank you for signing up! Please verify your email address by clicking the button below:</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto 24px;"><tr><td style="border-radius:8px;background-color:#3B82F6;"><a href="{action_url}" style="display:inline-block;padding:14px 32px;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;border-radius:8px;">Verify Email Address</a></td></tr></table><p style="margin:0 0 8px;font-size:14px;color:#6B7280;line-height:1.5;">This link will expire in <strong>{expiry_time}</strong>.</p><p style="margin:0;font-size:14px;color:#6B7280;">If you didn''t create an account, you can safely ignore this email.</p></td></tr><tr><td style="padding:24px 40px;background-color:#f9fafb;text-align:center;border-top:1px solid #e5e7eb;"><p style="margin:0;font-size:13px;color:#9CA3AF;">© {brand} — All rights reserved.</p></td></tr></table></td></tr></table></body></html>', NULL, true),

(NULL, 'email_verify', 'fa', 'تایید ایمیل شما', '<!DOCTYPE html><html dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f5;font-family:Tahoma,''Segoe UI'',Arial,sans-serif;direction:rtl;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f5;padding:40px 20px;"><tr><td align="center"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 6px rgba(0,0,0,0.07);"><tr><td style="background:linear-gradient(135deg,#3B82F6,#2563EB);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:24px;font-weight:700;">✉️ تایید ایمیل</h1></td></tr><tr><td style="padding:40px;"><p style="margin:0 0 16px;font-size:16px;color:#374151;">سلام <strong>{name}</strong>،</p><p style="margin:0 0 24px;font-size:16px;color:#374151;line-height:1.8;">از ثبت‌نام شما متشکریم! لطفاً ایمیل خود را با کلیک روی دکمه زیر تایید کنید:</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto 24px;"><tr><td style="border-radius:8px;background-color:#3B82F6;"><a href="{action_url}" style="display:inline-block;padding:14px 32px;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;border-radius:8px;">تایید آدرس ایمیل</a></td></tr></table><p style="margin:0 0 8px;font-size:14px;color:#6B7280;line-height:1.5;">این لینک تا <strong>{expiry_time}</strong> معتبر است.</p><p style="margin:0;font-size:14px;color:#6B7280;">اگر حسابی ایجاد نکرده‌اید، می‌توانید این ایمیل را نادیده بگیرید.</p></td></tr><tr><td style="padding:24px 40px;background-color:#f9fafb;text-align:center;border-top:1px solid #e5e7eb;"><p style="margin:0;font-size:13px;color:#9CA3AF;">© {brand} — تمامی حقوق محفوظ است.</p></td></tr></table></td></tr></table></body></html>', NULL, true),

(NULL, 'email_verify', 'tr', 'E-postanızı doğrulayın', '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f5;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,''Helvetica Neue'',Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f5;padding:40px 20px;"><tr><td align="center"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 6px rgba(0,0,0,0.07);"><tr><td style="background:linear-gradient(135deg,#3B82F6,#2563EB);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:24px;font-weight:700;">✉️ E-posta Doğrulama</h1></td></tr><tr><td style="padding:40px;"><p style="margin:0 0 16px;font-size:16px;color:#374151;">Merhaba <strong>{name}</strong>,</p><p style="margin:0 0 24px;font-size:16px;color:#374151;line-height:1.6;">Kaydolduğunuz için teşekkürler! Lütfen aşağıdaki butona tıklayarak e-postanızı doğrulayın:</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto 24px;"><tr><td style="border-radius:8px;background-color:#3B82F6;"><a href="{action_url}" style="display:inline-block;padding:14px 32px;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;border-radius:8px;">E-postayı Doğrula</a></td></tr></table><p style="margin:0 0 8px;font-size:14px;color:#6B7280;line-height:1.5;">Bu bağlantı <strong>{expiry_time}</strong> süresince geçerlidir.</p><p style="margin:0;font-size:14px;color:#6B7280;">Bir hesap oluşturmadıysanız bu e-postayı güvenle yok sayabilirsiniz.</p></td></tr><tr><td style="padding:24px 40px;background-color:#f9fafb;text-align:center;border-top:1px solid #e5e7eb;"><p style="margin:0;font-size:13px;color:#9CA3AF;">© {brand} — Tüm hakları saklıdır.</p></td></tr></table></td></tr></table></body></html>', NULL, true),

-- ═══════════════════════════════════════════
-- PASSWORD RESET
-- ═══════════════════════════════════════════
(NULL, 'password_reset', 'en', 'Reset your password', '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f5;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,''Helvetica Neue'',Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f5;padding:40px 20px;"><tr><td align="center"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 6px rgba(0,0,0,0.07);"><tr><td style="background:linear-gradient(135deg,#3B82F6,#2563EB);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:24px;font-weight:700;">🔒 Password Reset</h1></td></tr><tr><td style="padding:40px;"><p style="margin:0 0 16px;font-size:16px;color:#374151;">Hi <strong>{name}</strong>,</p><p style="margin:0 0 24px;font-size:16px;color:#374151;line-height:1.6;">We received a request to reset your password. Click the button below to choose a new one:</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto 24px;"><tr><td style="border-radius:8px;background-color:#3B82F6;"><a href="{action_url}" style="display:inline-block;padding:14px 32px;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;border-radius:8px;">Reset Password</a></td></tr></table><p style="margin:0 0 8px;font-size:14px;color:#6B7280;line-height:1.5;">This link will expire in <strong>{expiry_time}</strong>.</p><p style="margin:0;font-size:14px;color:#6B7280;">If you didn''t request this, please ignore this email.</p></td></tr><tr><td style="padding:24px 40px;background-color:#f9fafb;text-align:center;border-top:1px solid #e5e7eb;"><p style="margin:0;font-size:13px;color:#9CA3AF;">© {brand} — All rights reserved.</p></td></tr></table></td></tr></table></body></html>', NULL, true),

(NULL, 'password_reset', 'fa', 'بازنشانی رمز عبور', '<!DOCTYPE html><html dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f5;font-family:Tahoma,''Segoe UI'',Arial,sans-serif;direction:rtl;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f5;padding:40px 20px;"><tr><td align="center"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 6px rgba(0,0,0,0.07);"><tr><td style="background:linear-gradient(135deg,#3B82F6,#2563EB);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:24px;font-weight:700;">🔒 بازنشانی رمز عبور</h1></td></tr><tr><td style="padding:40px;"><p style="margin:0 0 16px;font-size:16px;color:#374151;">سلام <strong>{name}</strong>،</p><p style="margin:0 0 24px;font-size:16px;color:#374151;line-height:1.8;">درخواست بازنشانی رمز عبور دریافت شد. برای انتخاب رمز جدید روی دکمه زیر کلیک کنید:</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto 24px;"><tr><td style="border-radius:8px;background-color:#3B82F6;"><a href="{action_url}" style="display:inline-block;padding:14px 32px;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;border-radius:8px;">بازنشانی رمز عبور</a></td></tr></table><p style="margin:0 0 8px;font-size:14px;color:#6B7280;line-height:1.5;">این لینک تا <strong>{expiry_time}</strong> معتبر است.</p><p style="margin:0;font-size:14px;color:#6B7280;">اگر این درخواست را ارسال نکرده‌اید، لطفاً این ایمیل را نادیده بگیرید.</p></td></tr><tr><td style="padding:24px 40px;background-color:#f9fafb;text-align:center;border-top:1px solid #e5e7eb;"><p style="margin:0;font-size:13px;color:#9CA3AF;">© {brand} — تمامی حقوق محفوظ است.</p></td></tr></table></td></tr></table></body></html>', NULL, true),

(NULL, 'password_reset', 'tr', 'Şifrenizi sıfırlayın', '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f5;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,''Helvetica Neue'',Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f5;padding:40px 20px;"><tr><td align="center"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 6px rgba(0,0,0,0.07);"><tr><td style="background:linear-gradient(135deg,#3B82F6,#2563EB);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:24px;font-weight:700;">🔒 Şifre Sıfırlama</h1></td></tr><tr><td style="padding:40px;"><p style="margin:0 0 16px;font-size:16px;color:#374151;">Merhaba <strong>{name}</strong>,</p><p style="margin:0 0 24px;font-size:16px;color:#374151;line-height:1.6;">Şifrenizi sıfırlamak için bir istek aldık. Yeni bir şifre seçmek için aşağıdaki butona tıklayın:</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto 24px;"><tr><td style="border-radius:8px;background-color:#3B82F6;"><a href="{action_url}" style="display:inline-block;padding:14px 32px;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;border-radius:8px;">Şifreyi Sıfırla</a></td></tr></table><p style="margin:0 0 8px;font-size:14px;color:#6B7280;line-height:1.5;">Bu bağlantı <strong>{expiry_time}</strong> süresince geçerlidir.</p><p style="margin:0;font-size:14px;color:#6B7280;">Bu isteği siz yapmadıysanız bu e-postayı güvenle yok sayabilirsiniz.</p></td></tr><tr><td style="padding:24px 40px;background-color:#f9fafb;text-align:center;border-top:1px solid #e5e7eb;"><p style="margin:0;font-size:13px;color:#9CA3AF;">© {brand} — Tüm hakları saklıdır.</p></td></tr></table></td></tr></table></body></html>', NULL, true),

