(NULL, 'magic_link', 'en', 'Your login link', '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f5;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,''Helvetica Neue'',Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f5;padding:40px 20px;"><tr><td align="center"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 6px rgba(0,0,0,0.07);"><tr><td style="background:linear-gradient(135deg,#3B82F6,#2563EB);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:24px;font-weight:700;">🔗 Magic Link</h1></td></tr><tr><td style="padding:40px;"><p style="margin:0 0 16px;font-size:16px;color:#374151;">Hi <strong>{name}</strong>,</p><p style="margin:0 0 24px;font-size:16px;color:#374151;line-height:1.6;">Click the button below to sign in to your account instantly:</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto 24px;"><tr><td style="border-radius:8px;background-color:#3B82F6;"><a href="{action_url}" style="display:inline-block;padding:14px 32px;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;border-radius:8px;">Sign In Now</a></td></tr></table><p style="margin:0 0 8px;font-size:14px;color:#6B7280;line-height:1.5;">This link will expire in <strong>{expiry_time}</strong>.</p><p style="margin:0;font-size:14px;color:#6B7280;">If you didn''t request this, you can safely ignore this email.</p></td></tr><tr><td style="padding:24px 40px;background-color:#f9fafb;text-align:center;border-top:1px solid #e5e7eb;"><p style="margin:0;font-size:13px;color:#9CA3AF;">© {brand} — All rights reserved.</p></td></tr></table></td></tr></table></body></html>', NULL, true),

(NULL, 'magic_link', 'fa', 'لینک ورود شما', '<!DOCTYPE html><html dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f5;font-family:Tahoma,''Segoe UI'',Arial,sans-serif;direction:rtl;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f5;padding:40px 20px;"><tr><td align="center"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 6px rgba(0,0,0,0.07);"><tr><td style="background:linear-gradient(135deg,#3B82F6,#2563EB);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:24px;font-weight:700;">🔗 لینک ورود</h1></td></tr><tr><td style="padding:40px;"><p style="margin:0 0 16px;font-size:16px;color:#374151;">سلام <strong>{name}</strong>،</p><p style="margin:0 0 24px;font-size:16px;color:#374151;line-height:1.8;">برای ورود فوری به حساب خود روی دکمه زیر کلیک کنید:</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto 24px;"><tr><td style="border-radius:8px;background-color:#3B82F6;"><a href="{action_url}" style="display:inline-block;padding:14px 32px;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;border-radius:8px;">ورود به حساب</a></td></tr></table><p style="margin:0 0 8px;font-size:14px;color:#6B7280;line-height:1.5;">این لینک تا <strong>{expiry_time}</strong> معتبر است.</p><p style="margin:0;font-size:14px;color:#6B7280;">اگر این درخواست از طرف شما نبوده، لطفاً نادیده بگیرید.</p></td></tr><tr><td style="padding:24px 40px;background-color:#f9fafb;text-align:center;border-top:1px solid #e5e7eb;"><p style="margin:0;font-size:13px;color:#9CA3AF;">© {brand} — تمامی حقوق محفوظ است.</p></td></tr></table></td></tr></table></body></html>', NULL, true),

(NULL, 'magic_link', 'tr', 'Giriş bağlantınız', '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f5;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,''Helvetica Neue'',Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f5;padding:40px 20px;"><tr><td align="center"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 6px rgba(0,0,0,0.07);"><tr><td style="background:linear-gradient(135deg,#3B82F6,#2563EB);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:24px;font-weight:700;">🔗 Sihirli Bağlantı</h1></td></tr><tr><td style="padding:40px;"><p style="margin:0 0 16px;font-size:16px;color:#374151;">Merhaba <strong>{name}</strong>,</p><p style="margin:0 0 24px;font-size:16px;color:#374151;line-height:1.6;">Hesabınıza anında giriş yapmak için aşağıdaki butona tıklayın:</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto 24px;"><tr><td style="border-radius:8px;background-color:#3B82F6;"><a href="{action_url}" style="display:inline-block;padding:14px 32px;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;border-radius:8px;">Giriş Yap</a></td></tr></table><p style="margin:0 0 8px;font-size:14px;color:#6B7280;line-height:1.5;">Bu bağlantı <strong>{expiry_time}</strong> süresince geçerlidir.</p><p style="margin:0;font-size:14px;color:#6B7280;">Bu isteği siz yapmadıysanız güvenle yok sayabilirsiniz.</p></td></tr><tr><td style="padding:24px 40px;background-color:#f9fafb;text-align:center;border-top:1px solid #e5e7eb;"><p style="margin:0;font-size:13px;color:#9CA3AF;">© {brand} — Tüm hakları saklıdır.</p></td></tr></table></td></tr></table></body></html>', NULL, true),

